/**
 * The exercise library: every built-in exercise with a full written guide, so each one is
 * usable without a video. Content follows widely published strength-and-conditioning guidance
 * (e.g. NSCA / ACSM basics); it is general fitness information, not medical advice, and should
 * be reviewed by a qualified exercise professional before being presented as reviewed.
 *
 * Photos: an exercise only shows a photo once a person has checked it shows exactly that
 * exercise (food_photos table, key "ex_<id>"). Otherwise the written guide is shown with a
 * clean placeholder — never an unrelated image or an empty video player.
 */
import type { ExerciseKind } from '@/lib/liveWorkout';

export type Category = 'chest' | 'back' | 'shoulders' | 'arms' | 'legs' | 'glutes' | 'core' | 'cardio' | 'mobility' | 'flexibility';
export type Equip = 'none' | 'mat' | 'dumbbells' | 'barbell' | 'bench' | 'kettlebell' | 'cable' | 'machine' | 'band' | 'bar' | 'box' | 'bike' | 'rower' | 'rope' | 'pool' | 'shoes';
export type Level = 1 | 2 | 3;
export type Place = 'home' | 'gym' | 'outdoors';

export interface LibExercise {
  id: string;
  name: string;
  category: Category;
  kind: ExerciseKind;
  level: Level;
  equipment: Equip[];
  places: Place[];
  primary: string[];
  secondary: string[];
  description: string;
  start: string;
  steps: string[];
  breathing: string;
  /** Sets, reps (or seconds/minutes as text) and rest in seconds. */
  rx: { sets: number; reps: string; rest: number };
  mistakes: string[];
  safety: string[];
  easier?: string;
  harder?: string;
  /** Other library exercise ids that work the same muscles. */
  alternatives: string[];
}

