export const LIBRARY: LibExercise[] = ROWS.map(([id, name, category, kind, level, equipment, primary, secondary, description, start, steps, breathing, rx, mistakes, safety, easier, harder, alternatives]) => {
  const home = equipment.every((e) => HOME.has(e));
  const out = equipment.every((e) => OUT.has(e));
  return {
    id, name, category, kind, level, equipment,
    places: [...(home ? ['home' as const] : []), 'gym' as const, ...(out ? ['outdoors' as const] : [])],
    primary: primary.split(', ').filter(Boolean), secondary: secondary.split(', ').filter(Boolean),
    description, start, steps,
    breathing: breathing in BREATH ? BREATH[breathing as keyof typeof BREATH] : breathing,
    rx: { sets: rx[0], reps: rx[1], rest: rx[2] },
    mistakes,
    safety: [...new Set([...safety.map((s) => (s in SAFE ? SAFE[s as keyof typeof SAFE] : s)), SAFE.general])],
    easier, harder, alternatives,
  };
});

const BY_ID = new Map(LIBRARY.map((e) => [e.id, e]));
const BY_NAME = new Map(LIBRARY.map((e) => [e.name.toLowerCase(), e]));
/** Older names people may have in their history or AI plans. */
const ALIASES: Record<string, string> = {
  'dumbbell curl': 'db_curl', 'bicep curl': 'db_curl', 'biceps curl': 'db_curl', 'rowing machine': 'rowing', 'row': 'db_row', 'dumbbell row': 'db_row', 'bent-over row': 'barbell_row',
  'squats': 'squat', 'bodyweight squat': 'squat', 'air squat': 'squat', 'push-ups': 'push_up', 'pushup': 'push_up', 'press-up': 'push_up', 'pull-ups': 'pull_up', 'chin-up': 'pull_up',
  'shoulder press': 'db_shoulder_press', 'military press': 'overhead_press', 'rdl': 'romanian_deadlift', 'lunges': 'lunge', 'walking lunge': 'lunge', 'jump squats': 'squat_jump',
  'plank hold': 'plank', 'sit-up': 'crunch', 'crunches': 'crunch', 'dips': 'triceps_dip', 'bench dip': 'triceps_dip', 'glute bridges': 'glute_bridge', 'hip thrusts': 'hip_thrust',
  'skipping': 'jump_rope', 'run': 'running', 'jog': 'running', 'jogging': 'running', 'walk': 'walking', 'bike': 'cycling', 'stationary bike': 'cycling', 'swim': 'swimming',
  'chest press': 'chest_press_machine', 'seated row': 'seated_cable_row', 'cable row': 'seated_cable_row', 'kettlebell deadlift': 'kb_deadlift', 'calf raises': 'calf_raise',
};

/** Find a library exercise by id or by (roughly) its name. */
export function findExercise(nameOrId: string | null | undefined): LibExercise | undefined {
  if (!nameOrId) return undefined;
  const n = nameOrId.trim().toLowerCase();
  return BY_ID.get(n) ?? BY_NAME.get(n) ?? BY_ID.get(ALIASES[n] ?? '') ?? BY_NAME.get(n.replace(/s$/, '')) ??
    BY_ID.get(ALIASES[n.replace(/\s*\(.*\)$/, '')] ?? '') ?? BY_NAME.get(n.replace(/^(dumbbell|db|barbell|bodyweight)\s+/, ''));
}

/** Alternatives that suit the person's equipment and level (falls back to any alternative). */
export function alternativesFor(ex: LibExercise, opts: { equipment?: Equip[]; maxLevel?: Level } = {}): LibExercise[] {
  const fits = (e: LibExercise) => (!opts.equipment || e.equipment.every((q) => q === 'none' || q === 'mat' || opts.equipment!.includes(q))) && (!opts.maxLevel || e.level <= opts.maxLevel);
  const direct = ex.alternatives.map((id) => BY_ID.get(id)).filter((e): e is LibExercise => !!e);
  const same = LIBRARY.filter((e) => e.id !== ex.id && e.category === ex.category && !direct.includes(e));
  const ordered = [...direct, ...same];
  const good = ordered.filter(fits);
  return (good.length ? good : direct).slice(0, 4);
}

/** Photo key for an exercise (shown only once a person has checked the photo). */
export const exercisePhotoKey = (ex: LibExercise) => `ex_${ex.id}`;
